//! Parity of the `Text` editing API (stylize, divide, split, truncate,
//! join, expand_tabs, ...) with Python Rich 15, using
//! `tests/fixtures/text_ops.golden` (generated by
//! `scripts/gen_text_golden.py`).
//!
//! Each case builds a `Text`, applies a list of operations and compares the
//! plain text and per-character styles of every resulting `Text` (plus any
//! counts or styles the operations return). The golden file uses character
//! offsets; they are converted to byte offsets here.

use fast_rich::style::{Color, Style};
use fast_rich::text::{Overflow, Text};

const GOLDEN: &str = include_str!("fixtures/text_ops.golden");

#[derive(Default)]
struct Case {
    setup: Vec<String>,
    ops: Vec<String>,
    expected: Vec<String>,
}

fn parse_golden() -> Vec<Case> {
    let mut cases: Vec<Case> = Vec::new();
    for line in GOLDEN.lines() {
        match line.split(' ').next() {
            Some("C") => cases.push(Case::default()),
            Some("B") | Some("T") => cases.last_mut().unwrap().setup.push(line.to_string()),
            Some("O") => {
                let case = cases.last_mut().unwrap();
                // Results of an op (N/S lines) follow it; keep them in order.
                case.ops.push(line.to_string());
            }
            Some("P") | Some("R") | Some("N") | Some("S") => {
                cases.last_mut().unwrap().expected.push(line.to_string())
            }
            _ => {}
        }
    }
    cases
}

fn hex(s: &str) -> String {
    if s == "-" {
        return String::new();
    }
    let bytes: Vec<u8> = (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex"))
        .collect();
    String::from_utf8(bytes).expect("utf-8")
}

fn to_hex(s: &str) -> String {
    if s.is_empty() {
        return "-".into();
    }
    s.bytes().map(|b| format!("{b:02x}")).collect()
}

fn style(s: &str) -> Style {
    if s == "-" {
        Style::new()
    } else {
        Style::parse(&s.replace('+', " "))
    }
}

/// Character offset -> byte offset (offsets past the end stay past it).
fn byte_offset(text: &Text, chars: usize) -> usize {
    let plain = text.plain_text();
    let count = plain.chars().count();
    if chars >= count {
        plain.len() + (chars - count)
    } else {
        plain.char_indices().nth(chars).unwrap().0
    }
}

/// `BrightGreen` -> `bright_green`, matching Rich's color names.
fn color_name(color: Color) -> String {
    let mut out = String::new();
    for (i, c) in format!("{color:?}").chars().enumerate() {
        if c.is_ascii_uppercase() {
            if i > 0 {
                out.push('_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

fn describe(style: &Style) -> String {
    let mut parts = Vec::new();
    if let Some(c) = style.foreground.filter(|c| *c != Color::Default) {
        parts.push(color_name(c));
    }
    if let Some(c) = style.background.filter(|c| *c != Color::Default) {
        parts.push(format!("on_{}", color_name(c)));
    }
    let flags: String = [
        ('b', style.bold),
        ('d', style.dim),
        ('i', style.italic),
        ('u', style.underline),
        ('s', style.strikethrough),
        ('r', style.reverse),
    ]
    .iter()
    .filter(|(_, on)| *on)
    .map(|(f, _)| *f)
    .collect();
    if !flags.is_empty() {
        parts.push(flags);
    }
    parts.join(":")
}

fn result_lines(text: &Text, out: &mut Vec<String>) {
    out.push(format!("P {}", to_hex(&text.plain_text())));
    let mut runs: Vec<(usize, usize, String)> = Vec::new();
    let mut i = 0;
    for span in &text.spans {
        let desc = describe(&text.style.combine(&span.style));
        for _ in span.text.chars() {
            match runs.last_mut() {
                Some(last) if last.2 == desc && last.1 == i => last.1 = i + 1,
                _ => runs.push((i, i + 1, desc.clone())),
            }
            i += 1;
        }
    }
    for (start, end, desc) in runs.into_iter().filter(|r| !r.2.is_empty()) {
        out.push(format!("R {start} {end} {desc}"));
    }
}

/// Apply one op to every text. Returns `None` if the op needs a feature
/// this build does not have.
fn apply(texts: Vec<Text>, op: &str, out: &mut Vec<String>) -> Option<Vec<Text>> {
    let a: Vec<&str> = op.split(' ').skip(1).collect();
    let name = a[0];
    let num = |i: usize| -> usize { a[i].parse().unwrap() };
    if name == "join" {
        let sep = Text::plain(hex(a[1])).style(style(a[2]));
        return Some(vec![sep.join(texts)]);
    }
    let mut new = Vec::new();
    for mut t in texts {
        match name {
            "stylize" | "stylize_before" | "copy_styles" => {
                let (s, e) = (byte_offset(&t, num(2)), byte_offset(&t, num(3)));
                match name {
                    "stylize" => t.stylize(style(a[1]), s, e),
                    "stylize_before" => t.stylize_before(style(a[1]), s, e),
                    _ => {
                        let mut other = Text::plain(t.plain_text());
                        other.stylize(style(a[1]), s, e);
                        t.copy_styles(&other);
                    }
                }
            }
            "highlight_words" => {
                let words: Vec<String> = a[3].split(',').map(hex).collect();
                let n = t.highlight_words(&words, style(a[1]), a[2] == "1");
                out.push(format!("N {n}"));
            }
            "highlight_regex" => {
                #[cfg(feature = "regex")]
                {
                    let re = regex::Regex::new(&hex(a[2])).unwrap();
                    out.push(format!("N {}", t.highlight_regex(&re, style(a[1]))));
                }
                #[cfg(not(feature = "regex"))]
                return None;
            }
            "append_tokens" => {
                t.append_tokens([(hex(a[1]), style(a[2]))]);
            }
            "append_text" => {
                t.append_text(&Text::plain(hex(a[1])).style(style(a[2])));
            }
            "divide" => {
                let offsets: Vec<usize> = if a[1] == "-" {
                    Vec::new()
                } else {
                    a[1].split(',')
                        .map(|o| byte_offset(&t, o.parse().unwrap()))
                        .collect()
                };
                new.extend(t.divide(offsets));
                continue;
            }
            "split" => {
                new.extend(t.split(&hex(a[1]), a[2] == "1"));
                continue;
            }
            "fit" => {
                new.extend(t.fit(num(1)));
                continue;
            }
            "right_crop" => t.right_crop(num(1)),
            "truncate" => {
                let overflow = match a[2] {
                    "crop" => Overflow::Truncate,
                    "ellipsis" => Overflow::Ellipsis,
                    "ignore" => Overflow::Visible,
                    _ => Overflow::Wrap,
                };
                t.truncate(num(1), Some(overflow), a[3] == "1");
            }
            "pad" | "pad_left" | "pad_right" => {
                let c = hex(a[2]).chars().next().unwrap();
                match name {
                    "pad" => t.pad(num(1), c),
                    "pad_left" => t.pad_left(num(1), c),
                    _ => t.pad_right(num(1), c),
                }
            }
            "set_length" => t.set_length(num(1)),
            "expand_tabs" => t.expand_tabs(num(1)),
            "rstrip" => t.rstrip(),
            "rstrip_end" => t.rstrip_end(num(1)),
            "remove_suffix" => t.remove_suffix(&hex(a[1])),
            "style_at" => {
                let desc = describe(&t.get_style_at_offset(byte_offset(&t, num(1))));
                out.push(format!("S {}", if desc.is_empty() { "-" } else { &desc }));
            }
            "detect_indentation" => out.push(format!("N {}", t.detect_indentation())),
            "indent_guides" => {
                let size = (a[1] != "-").then(|| num(1));
                let c = hex(a[2]).chars().next().unwrap();
                t = t.with_indent_guides(size, c, style(a[3]));
            }
            other => panic!("unknown op {other}"),
        }
        new.push(t);
    }
    Some(new)
}

fn build(setup: &[String]) -> Text {
    let mut text = Text::new();
    for line in setup {
        let a: Vec<&str> = line.split(' ').collect();
        match a[0] {
            "B" => text.style = style(a[1]),
            _ => {
                text.append_tokens([(hex(a[1]), style(a[2]))]);
            }
        }
    }
    text
}

#[test]
fn text_ops_match_python_rich() {
    let cases = parse_golden();
    assert!(cases.len() > 600, "golden fixture looks truncated");

    let mut failures = Vec::new();
    let mut checked = 0;
    'cases: for case in &cases {
        let mut texts = vec![build(&case.setup)];
        let mut actual = Vec::new();
        for op in &case.ops {
            match apply(texts, op, &mut actual) {
                Some(t) => texts = t,
                None => continue 'cases,
            }
        }
        for t in &texts {
            result_lines(t, &mut actual);
        }
        checked += 1;
        if actual != case.expected {
            failures.push(format!(
                "setup: {:?}\n  ops: {:?}\n  rich:      {:?}\n  fast-rich: {:?}",
                case.setup, case.ops, case.expected, actual
            ));
        }
    }
    assert!(checked > 450, "too few cases checked: {checked}");
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from Python Rich:\n{}",
        failures.len(),
        checked,
        failures
            .iter()
            .take(10)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
